{"updateComponents":{"surfaceId":"event-form","components":[{"id":"root","component":"Card","title":"New event","description":"Schedule a calendar event and invite attendees.","children":["form"],"style":{"maxWidth":"640px","width":"100%","marginHorizontal":"auto"}},{"id":"form","component":"Form","name":"createEvent","children":["fields","actions"],"on":{"submit":{"event":{"name":"event.save","context":{"title":{"path":"/event/title"},"startDate":{"path":"/event/startDate"},"endDate":{"path":"/event/endDate"},"startTime":{"path":"/event/startTime"},"endTime":{"path":"/event/endTime"},"attendees":{"path":"/event/attendees"},"description":{"path":"/event/description"},"reminder":{"path":"/event/reminder"}}}}}},{"id":"fields","component":"Stack","gap":"md","children":["title","dates","times","attendees","description","reminder"]},{"id":"title","component":"Input","label":"Title","name":"title","placeholder":"e.g. Quarterly planning","value":{"path":"/event/title"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/event/title"}}},"message":"Give the event a title."}]},{"id":"dates","component":"DateRangePicker","label":"Dates","name":"dates","start":{"path":"/event/startDate"},"end":{"path":"/event/endDate"}},{"id":"times","component":"Grid","columns":{"base":1,"sm":2},"gap":"md","children":["startTime","endTime"]},{"id":"startTime","component":"TimePicker","label":"Start time","name":"startTime","value":{"path":"/event/startTime"},"step":15},{"id":"endTime","component":"TimePicker","label":"End time","name":"endTime","value":{"path":"/event/endTime"},"step":15},{"id":"attendees","component":"ChipInput","label":"Attendees","name":"attendees","placeholder":"Add an email and press Enter","values":{"path":"/event/attendees"},"suggestions":{"path":"/suggestions"}},{"id":"description","component":"Textarea","label":"Description","name":"description","placeholder":"Agenda, links, notes…","rows":4,"autosize":true,"maxRows":10,"value":{"path":"/event/description"}},{"id":"reminder","component":"Switch","label":"Reminder","name":"reminder","description":"Notify attendees 15 minutes before the event starts.","checked":{"path":"/event/reminder"}},{"id":"actions","component":"Stack","direction":"horizontal","gap":"sm","justify":"end","children":["cancel","save"]},{"id":"cancel","component":"Button","label":"Cancel","variant":"ghost","on":{"press":{"event":{"name":"event.cancel"}}}},{"id":"save","component":"Button","label":"Save","variant":"default","icon":"check","submit":true}]}}
